import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadTitleFont = makeLoadFont('SpaceGrotesk');
const loadItemFont = makeLoadFont('Inter');

const { fontFamily: titleFontFamily } = loadTitleFont();
const { fontFamily: itemFontFamily } = loadItemFont();



export type ChecklistProps = Record<string, any>;

const Checklist: React.FC<ChecklistProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Key Focus Areas",
  titleColor = "#0f172a",
  items = ["Wishes", "Values", "Priorities"],
  itemTextColor = "#334155",
  checkboxColor = "#3b82f6",
  checkmarkColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const titleStart = 10;
  
  const titleOpacity = interpolate(
    frame,
    [titleStart, titleStart + 20],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const titleY = interpolate(
    frame,
    [titleStart, titleStart + 20],
    [30, 0],
    { easing: Easing.out(Easing.cubic), extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", paddingLeft: width * 0.15 }}>
      {/* Title */}
      {title && (
        <div
          style={{
            fontFamily: titleFontFamily,
            fontSize: height * 0.08,
            fontWeight: 700,
            color: titleColor,
            marginBottom: height * 0.08,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {title}
        </div>
      )}

      {/* Checklist Items */}
      <div style={{ display: "flex", flexDirection: "column", gap: height * 0.05, transition: "none" }}>
        {items.map((item, index) => {
          const itemStart = 20 + index * 15;
          const checkStart = itemStart + 20;

          const itemOpacity = interpolate(
            frame,
            [itemStart, itemStart + 15],
            [0, 1],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          const itemX = interpolate(
            frame,
            [itemStart, itemStart + 15],
            [-30, 0],
            { easing: Easing.out(Easing.cubic), extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          const bgFillScale = spring({
            frame: frame - checkStart,
            fps,
            config: { overshootClamping: true, damping: 15 },
          });

          const checkScale = spring({
            frame: frame - checkStart - 5,
            fps,
            config: { damping: 10, mass: 0.8 },
          });

          const boxSize = height * 0.06;

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                opacity: itemOpacity,
                transform: `translateX(${itemX}px)`,
                transition: "none",
              }}
            >
              {/* Checkbox */}
              <div
                style={{
                  position: "relative",
                  width: boxSize,
                  height: boxSize,
                  border: `4px solid ${checkboxColor}`,
                  borderRadius: boxSize * 0.25,
                  marginRight: width * 0.02,
                  overflow: "hidden",
                  flexShrink: 0,
                  transition: "none",
                }}
              >
                {/* Background Fill */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundColor: checkboxColor,
                    transform: `scale(${bgFillScale})`,
                    transformOrigin: "center",
                    transition: "none",
                  }}
                />
                
                {/* Checkmark Icon */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transform: `scale(${checkScale})`,
                    transition: "none",
                  }}
                >
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke={checkmarkColor}
                    strokeWidth="3.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    style={{ width: "70%", height: "70%" }}
                  >
                    <polyline points="20 6 9 17 4 12" />
                  </svg>
                </div>
              </div>

              {/* Item Text */}
              <div
                style={{
                  fontFamily: itemFontFamily,
                  fontSize: height * 0.06,
                  fontWeight: 500,
                  color: itemTextColor,
                  transition: "none",
                  maxWidth: width * 0.6,
                }}
              >
                {item}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default Checklist;